1007		if err != nil {
1008			t.Fatalf("ProposalsSnapshot: %v", err)
1009		}
1010		if again.Registered[0].State != "passed" || again.Voting[0].State != "passed" {
1011			t.Fatalf("snapshot shares state with store: %+v", again)
1012		}
1013	}
1014	
1015	func TestProposalsSnapshotConsistentUnderConcurrentExecute(t *testing.T) {
1016		store, _ := openTempStore(t, 1000)
1017		defer store.Close()
1018		// 登记提案与投票提案最初都为 passed 且时间锁已到期；
1019		// 执行方先执行登记提案，再执行投票提案。快照只允许出现
1020		// (passed,passed)、(executed,passed)、(executed,executed) 三种完整组合，
1021		// 不得出现登记提案仍为 passed 而投票提案已 executed 的混杂状态。
1022		mustRegister(t, store, "gip-reg", 0, "transfer:audits:100")
1023		mustCreateVote(t, store, baseVoteInput("gip-vote"))
1024		if _, err := store.CastVote("gip-vote", "alice", true, 100); err != nil {
1025			t.Fatalf("CastVote: %v", err)
1026		}
1027		if _, err := store.TallyVote("gip-vote", 200); err != nil {
1028			t.Fatalf("TallyVote: %v", err)
1029		}
1030	
1031		var wg sync.WaitGroup
1032		start := make(chan struct{})
1033		stop := make(chan struct{})
1034		wg.Add(1)
1035		go func() {
1036			defer wg.Done()
1037			<-start
1038			_, _ = store.Execute("gip-reg", 300)
1039			_, _ = store.Execute("gip-vote", 300)
1040			close(stop)
1041		}()
1042		for i := 0; i < 8; i++ {
1043			wg.Add(1)
1044			go func() {
1045				defer wg.Done()
1046				<-start
1047				for {
1048					select {
1049					case <-stop:
1050						return
1051					default:
1052					}
1053					snap, err := store.ProposalsSnapshot()
1054					if err != nil {
1055						t.Errorf("ProposalsSnapshot: %v", err)
1056						return
1057					}
1058					if len(snap.Registered) != 1 || len(snap.Voting) != 1 {
1059						t.Errorf("snapshot sizes = %d/%d, want 1/1", len(snap.Registered), len(snap.Voting))
1060						return
1061					}
1062					reg := snap.Registered[0].State
1063					vote := snap.Voting[0].State
1064					if reg == "passed" && vote == "executed" {
1065						t.Errorf("mixed committed states: registered=%s voting=%s", reg, vote)
1066						return
1067					}
1068				}
1069			}()
1070		}
1071		close(start)
1072		wg.Wait()
1073	}
1074	
1075	// TestTallyAtInt64WeightBoundary：合法成员总权重恰好为有符号 64 位整数上限时，
1076	// 首次计票、查询结论与重开后的汇总/结论都不能因数值边界改变：
1077	// 参与量恰好等于法定人数（MaxInt64）且赞成严格多于反对即通过；
1078	// 无票时参与量为 0，绝不能把成员总权重当成参与量。
1079	func TestTallyAtInt64WeightBoundary(t *testing.T) {
1080		max := int64(math.MaxInt64)
1081	
1082		// 单成员持有全部权重且赞成：for=MaxInt64、against=0、turnout=MaxInt64
1083		// 恰好达到法定人数 MaxInt64 => 通过。
1084		t.Run("single member exactly quorum", func(t *testing.T) {
1085			path := filepath.Join(t.TempDir(), "treasury.json")
1086			store, err := InitTreasury(path, 0)
1087			if err != nil {
1088				t.Fatal(err)
1089			}
1090			in := &CreateVoteInput{
1091				ID: "gip-max-one", Members: []VoteMember{{ID: "a", Weight: max}},
1092				Quorum: max, StartAt: 0, Deadline: 10, TimelockEnd: 10,
1093			}
1094			mustCreateVote(t, store, in)
1095			if _, err := store.CastVote("gip-max-one", "a", true, 5); err != nil {
1096				t.Fatal(err)
1097			}
1098			res, err := store.TallyVote("gip-max-one", 10)
1099			if err != nil {
1100				t.Fatalf("tally: %v", err)
1101			}
1102			if !res.Passed || res.ForWeight != max || res.AgainstWeight != 0 || res.Turnout != max || res.Quorum != max {
1103				t.Fatalf("boundary tally = %+v, want passed for=turnout=quorum=MaxInt64", res)
1104			}
1105			store.Close()
1106	
1107			// 重开后查询结论与首次计票完全一致。
1108			reopened, err := Open(path)
1109			if err != nil {
1110				t.Fatalf("reopen: %v", err)
1111			}
1112			defer reopened.Close()
1113			v, ok, err := reopened.VoteProposal("gip-max-one")
1114			if err != nil || !ok {
1115				t.Fatalf("query: %v ok=%v", err, ok)
1116			}
1117			if v.State != "passed" || v.Tally == nil || !v.Tally.Passed ||
1118				v.Tally.ForWeight != max || v.Tally.Turnout != max || v.Tally.AgainstWeight != 0 ||
1119				v.Tally.TalliedAt != 10 || v.TotalWeight != max {
1120				t.Fatalf("reopened boundary view = state=%s tally=%+v total=%d", v.State, v.Tally, v.TotalWeight)
1121			}
1122		})
1123	
1124		// 总权重 MaxInt64 拆为 MaxInt64-1（赞成）与 1（反对）：参与量恰好到上限、
1125		// 赞成严格多于反对 => 通过；此场景覆盖两侧相加恰好等于 MaxInt64 的边界。
1126		t.Run("split weights turnout exactly max", func(t *testing.T) {
1127			store, _ := openTempStore(t, 0)
1128			defer store.Close()
1129			in := &CreateVoteInput{
1130				ID: "gip-max-split",
1131				Members: []VoteMember{
1132					{ID: "a", Weight: max - 1},
1133					{ID: "b", Weight: 1},
1134				},
1135				Quorum: max, StartAt: 0, Deadline: 10, TimelockEnd: 10,
1136			}
1137			mustCreateVote(t, store, in)
1138			if _, err := store.CastVote("gip-max-split", "a", true, 5); err != nil {
1139				t.Fatal(err)
1140			}
1141			if _, err := store.CastVote("gip-max-split", "b", false, 6); err != nil {
1142				t.Fatal(err)
1143			}
1144			res, err := store.TallyVote("gip-max-split", 10)
1145			if err != nil {
1146				t.Fatalf("tally: %v", err)
1147			}
1148			if !res.Passed || res.ForWeight != max-1 || res.AgainstWeight != 1 || res.Turnout != max {
1149				t.Fatalf("split boundary tally = %+v, want passed turnout=MaxInt64", res)
1150			}
1151		})
1152	
1153		// 没有任何人投票：参与量必须是 0，而不是成员总权重 MaxInt64；即使法定人数为 1 也拒绝。
1154		t.Run("no ballots turnout zero not total", func(t *testing.T) {
1155			store, _ := openTempStore(t, 0)
1156			defer store.Close()
1157			in := &CreateVoteInput{
1158				ID: "gip-max-novote", Members: []VoteMember{{ID: "a", Weight: max}},
1159				Quorum: 1, StartAt: 0, Deadline: 10, TimelockEnd: 10,
1160			}
1161			mustCreateVote(t, store, in)
1162			res, err := store.TallyVote("gip-max-novote", 10)
1163			if err != nil {
1164				t.Fatalf("tally: %v", err)
1165			}
1166			if res.Passed || res.ForWeight != 0 || res.AgainstWeight != 0 || res.Turnout != 0 {
1167				t.Fatalf("no-ballot tally = %+v, want rejected with zero turnout", res)
1168			}
1169			v, _, _ := store.VoteProposal("gip-max-novote")
1170			if v.State != "rejected" || v.Tally == nil || v.Tally.Passed {
1171				t.Fatalf("no-ballot query state=%s tally=%+v, want rejected/not-passed", v.State, v.Tally)
1172			}
1173		})
1174	}
1175	
1176	// TestRepeatTallyAfterExecutionIgnoresEarlyNow：已有结论后，即使再次传入截止前
1177	// 时间，也返回首次结论与首次计票时间；提案后来已执行时，状态不得退回 passed。
1178	func TestRepeatTallyAfterExecutionIgnoresEarlyNow(t *testing.T) {
1179		store, _ := openTempStore(t, 1000)
1180		defer store.Close()
1181		mustCreateVote(t, store, baseVoteInput("gip-again"))
1182		if _, err := store.CastVote("gip-again", "alice", true, 100); err != nil {
1183			t.Fatal(err)
1184		}
