1186		if err != nil || !first.Passed || first.TalliedAt != 200 {
1187			t.Fatalf("first tally: %+v err=%v", first, err)
1188		}
1189		// 执行后状态变为 executed。
1190		if _, err := store.Execute("gip-again", 300); err != nil {
1191			t.Fatalf("execute: %v", err)
1192		}
1193	
1194		// 传入截止前时间再次计票：不是“时间未到”，而是返回首次结论与首次时间。
1195		early, err := store.TallyVote("gip-again", 150)
1196		if err != nil {
1197			t.Fatalf("repeat tally with early now must not error: %v", err)
1198		}
1199		if !early.Passed || early.TalliedAt != 200 || early.ForWeight != 600 || early.Turnout != 600 {
1200			t.Fatalf("repeat tally = %+v, want first result tallied_at=200", early)
1201		}
1202		v, _, _ := store.VoteProposal("gip-again")
1203		if v.State != "executed" {
1204			t.Fatalf("state regressed to %s, want executed", v.State)
1205		}
1206		if v.Tally == nil || !v.Tally.Passed || v.Tally.TalliedAt != 200 {
1207			t.Fatalf("query tally after execution = %+v", v.Tally)
1208		}
1209	
1210		// 截止前计票若发生在首次之前仍应明确报时间未到（对照另一项未计票提案）。
1211		mustCreateVote(t, store, baseVoteInput("gip-fresh"))
1212		if _, err := store.TallyVote("gip-fresh", 199); !errors.Is(err, ErrTallyRejected) {
1213			t.Fatalf("first early tally err=%v, want ErrTallyRejected", err)
1214		}
1215		fv, _, _ := store.VoteProposal("gip-fresh")
1216		if fv.State != "voting" || fv.Tally != nil {
1217			t.Fatalf("rejected early tally changed state: %s %+v", fv.State, fv.Tally)
1218		}
1219	}
1220	
1221	// TestTamperedTallyConclusionKeepsFile：保存的赞成/反对权重或提案状态与票据
1222	// 重放不一致时，必须作为状态损坏拒绝打开，错误文本能区分原因，且原文件保留。
1223	func TestTamperedTallyConclusionKeepsFile(t *testing.T) {
1224		dir := t.TempDir()
1225		path := filepath.Join(dir, "treasury.json")
1226		store, err := InitTreasury(path, 1000)
1227		if err != nil {
1228			t.Fatal(err)
1229		}
1230		mustCreateVote(t, store, baseVoteInput("gip-ctamper"))
1231		if _, err := store.CastVote("gip-ctamper", "alice", true, 150); err != nil {
1232			t.Fatal(err)
1233		}
1234		if _, err := store.TallyVote("gip-ctamper", 200); err != nil {
1235			t.Fatal(err)
1236		}
1237		store.Close()
1238	
1239		good, err := os.ReadFile(path)
1240		if err != nil {
1241			t.Fatal(err)
1242		}
1243		mutate := func(fn func(p map[string]any)) []byte {
1244			var clone map[string]any
1245			if err := json.Unmarshal(good, &clone); err != nil {
1246				t.Fatal(err)
1247			}
1248			p := clone["vote_proposals"].(map[string]any)["gip-ctamper"].(map[string]any)
1249			fn(p)
1250			raw, err := json.MarshalIndent(clone, "", "  ")
1251			if err != nil {
1252				t.Fatal(err)
1253			}
1254			return append(raw, '\n')
1255		}
1256	
1257		cases := map[string]struct {
1258			raw     []byte
1259			wantSub string
1260		}{
1261			// 票据是 600 赞成、法定人数 600，本应 passed；状态被改成 rejected。
1262			"state contradicts ballots": {
1263				mutate(func(p map[string]any) { p["state"] = "rejected" }),
1264				"does not match quorum/majority replay",
1265			},
1266			// 保存的反对权重与票据重放不符（票据里没有反对票）。
1267			"tally against weight disagrees": {
1268				mutate(func(p map[string]any) {
1269					p["tally"].(map[string]any)["against_weight"] = 1
1270				}),
1271				"do not replay ballots",
1272			},
1273			// 代表票重与委托后归集权重不符，走同一份票重核对规则。
1274			"delegated ballot weight disagrees": {
1275				mutate(func(p map[string]any) {
1276					p["ballots"].([]any)[0].(map[string]any)["weight"] = 599
1277				}),
1278				"does not match roster delegation",
1279			},
1280		}
1281		for name, tc := range cases {
1282			t.Run(name, func(t *testing.T) {
