263	
264	func TestReceiptOrderAndPersistence(t *testing.T) {
265		path := filepath.Join(t.TempDir(), "treasury.json")
266		store, err := InitTreasury(path, 1000)
267		if err != nil {
268			t.Fatal(err)
269		}
270		mustRegister(t, store, "gip-b", 0, "transfer:b:100")
271		mustRegister(t, store, "gip-a", 0, "transfer:a:200")
272		if _, err := store.Execute("gip-b", 1); err != nil {
273			t.Fatal(err)
274		}
275		if _, err := store.Execute("gip-a", 2); err != nil {
276			t.Fatal(err)
277		}
278		if err := store.Close(); err != nil {
279			t.Fatal(err)
