19	func main() {
20		command := "demo"
21		if len(os.Args) > 1 {
22			command = os.Args[1]
23		}
24		args := os.Args[2:]
25		switch command {
26		case "demo":
27			runDemo()
28		case "version":
29			fmt.Println(versionText)
30		case "help", "-h", "--help":
31			usage()
32		case "init":
33			runInit(args)
34		case "register":
35			runRegister(args)
36		case "create-vote":
37			runCreateVote(args)
38		case "vote":
39			runVote(args)
40		case "tally":
41			runTally(args)
42		case "execute":
43			runExecute(args)
44		case "balances":
45			runBalances(args)
46		case "proposal":
