// ballotFieldKind 按字段实际写出 JSON 的首字节归类其 JSON 类型。
// RawMessage 是从合法 JSON 文档中取出的单个值，首字节足以区分
// 字符串/布尔/数字/数组/对象，无需再次解码。
func ballotFieldKind(raw json.RawMessage) string {
	for _, c := range raw {
		switch c {
		case ' ', '\t', '\n', '\r':
			continue
		case '"':
			return "string"
		case 't', 'f':
			return "boolean"
		case '[':
			return "array"
		case '{':
			return "object"
		default:
			return "number" // 数字（含小数、指数）与符号都以数字或 '-' 起始
		}
	}
	return "invalid json"
}

